import{_ as a}from"./chunks/收.BlmX_8S1.js";import{_ as i,o as l,c as o,a2 as s,j as e,a as t}from"./chunks/framework.DfDAiEgj.js";const n="/2bPM/img/resume_nophone2.jpg",h="/2bPM/img/rope.png",p="/2bPM/img/%E8%AF%81%E5%88%B8%E4%BB%8E%E4%B8%9A1.png",d="/2bPM/img/%E8%AF%81%E5%88%B8%E4%BB%8E%E4%B8%9A2.png",b="/2bPM/img/%E5%9F%BA%E9%87%91%E4%BB%8E%E4%B8%9A.png",m="/2bPM/img/baidu_kaifa.png",c="/2bPM/img/idea_time.png",g="/2bPM/img/kaifa_online.png",u="/2bPM/img/baidu_gujia.jpg",_="/2bPM/img/baidu_gujia_newest.png",B=JSON.parse('{"title":"To be AI PM，百度用了我战略idea？","description":"","frontmatter":{},"headers":[],"relativePath":"get_started.md","filePath":"get_started.md","lastUpdated":null}'),f={name:"get_started.md"};function k(P,r,v,A,M,E){return l(),o("div",null,[...r[0]||(r[0]=[s('<h1 id="to-be-ai-pm-百度用了我战略idea" tabindex="-1">To be AI PM，百度用了我战略idea？ <a class="header-anchor" href="#to-be-ai-pm-百度用了我战略idea" aria-label="Permalink to &quot;To be AI PM，百度用了我战略idea？&quot;">​</a></h1><p>AI产品经理是直接应用或间接涉及了AI技术，进而完成相关AI产品的设计、研发、推广、产品生命周期管理等工作的产品经理。由于AI的技术领域太多、且有更多和垂直行业结合的机会，导致细分AI领域的产品经理所需要的背景和能力可能大不相同。[1]</p><p><img src="'+n+'" alt="简历"></p><h2 id="点击下载整页简历pdf-带url" tabindex="-1"><a href="https://github.com/StevenJokess/2bPM/blob/master/%E8%94%A1%E8%88%92%E8%B5%B7-AI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86-GAN(MXNet-PyTorchTF2%E5%BC%80%E5%8F%91%E8%80%85)_nophone.pdf" target="_blank" rel="noreferrer">点击下载整页简历PDF（带URL）</a> <a class="header-anchor" href="#点击下载整页简历pdf-带url" aria-label="Permalink to &quot;[点击下载整页简历PDF（带URL）](https://github.com/StevenJokess/2bPM/blob/master/蔡舒起-AI产品经理-GAN(MXNet-PyTorchTF2开发者)_nophone.pdf)&quot;">​</a></h2><h2 id="项目目的" tabindex="-1">项目目的 <a class="header-anchor" href="#项目目的" aria-label="Permalink to &quot;项目目的&quot;">​</a></h2><p>本来这个项目是为了求职AI产品经理（避免<a href="https://www.zhihu.com/pub/reader/120204365/chapter/1396810398809669632" target="_blank" rel="noreferrer">^5</a>，可在学习技术的过程中，我发觉AI时代的病症与AI大规模应用后可能的悲惨后果，既然失业良久了，也就不必执着求职了，好好批判下。后续的主要研究方向为AI的产品化与产品化的可能社会影响。</p><ul><li><p>Linkedin（Writing can&#39;t make money, but can make friends.）<a href="https://www.linkedin.com/in/%E8%88%92%E8%B5%B7-%E8%94%A1-b609001b7/" target="_blank" rel="noreferrer">https://www.linkedin.com/in/舒起-蔡-b609001b7/</a></p></li><li><p>Linkedin(had 800 friends in AI field , but now has been permanently restricted）见“平台随意封号”章节：<a href="https://stevenjokess.github.io/2bPM/AI_pipan.html#id27" target="_blank" rel="noreferrer">https://stevenjokess.github.io/2bPM/AI_pipan.html#id27</a></p></li><li><p>Email me: <a href="mailto:llgg8679@qq.com" target="_blank" rel="noreferrer">llgg8679@qq.com</a></p></li><li><p>Telegram me: <a href="https://t.me/StevenJokes" target="_blank" rel="noreferrer">https://t.me/StevenJokes</a></p></li><li><p>常见问题：<a href="https://stevenjokess.github.io/2bPM/chapter_interview/question.html" target="_blank" rel="noreferrer">https://stevenjokess.github.io/2bPM/chapter_interview/question.html</a></p></li><li><p>模拟面试：<a href="https://stevenjokess.github.io/2bPM/chapter_interview/simulate_interview.html" target="_blank" rel="noreferrer">https://stevenjokess.github.io/2bPM/chapter_interview/simulate_interview.html</a></p></li><li><p>Be a Watcher：<a href="https://github.com/StevenJokess/2bPM/watchers" target="_blank" rel="noreferrer">https://github.com/StevenJokess/2bPM/watchers</a></p></li></ul><hr><p>评论区：</p><p>求职，失业在家鬼混3年</p><ul><li>金融方面：2020届的山西大学金融学专业的毕业生，获得三好学生学业奖学金，拥有会计、证券、基金从业证书，毕业论文是用Python的Statsmodel库里的VAR模型完成的《中美股市的联动性分析》</li><li>AI方面：大一参加数学建模了解了神经网络算法，后在网络金融课分享了鱼书的ppt，得知金融方面的非结构信息常用深度学习算法，之后阅读过二十几本人工智能相关书籍，在20年用4个月自学完了《动手学深度学习》预览版并动手翻译MXNet到PyTorch、TF2的GAN\\DCGAN，复现PyTorch、DJL等一系列深度学习移动端框架的Demo。</li><li>产品经理方面：虽然没有工作经历，但还是努力修炼了一系列的能力。战略能力上，在百度一面失败后，考虑到了百度开发者版的想法。沟通能力上，与MXNet的开发者交流无人社区冷淡情况。学习上，学习十余本产品有关的书，并自行总结了AI产品经理的工作内容和技能要求，用Docker部署成《To be AI PM》书。</li><li>体能方面：跳绳比赛成绩:30s单摇:66;30s双摇:60;三摇:11个;·在4*30男子团体单摇比赛,作为非体院唯一绳没断的第四棒,团体一同跳250.取得市和省级铜牌。（B站跳绳视频： bilibili.com/video/BV1W）随后,作为非社团成员,文案宣传跳绳燃脂效率高、方便,招新翻四倍。还有初级教练、裁判证;曾会单手俯卧撑、深蹲10个+；</li></ul><p>更多AI产品经理内容，可见：<a href="https://stevenjokess.github.io/2bPM/get_started.html" target="_blank" rel="noreferrer">https://stevenjokess.github.io/2bPM/get_started.html</a> AI时代批判与共产主义意识形态输出，见 <a href="https://stevenjokess.github.io/2bPM/AI_critical.html" target="_blank" rel="noreferrer">https://stevenjokess.github.io/2bPM/AI_critical.html</a> 更多及时内容，进QQ群：171097552 联系我：llgg867907127@qq.com 没工作，可以用付款的方式支持我继续创作：<img src="'+a+'" alt="收款码"></p><hr><h2 id="简历" tabindex="-1"><strong>简历</strong> <a class="header-anchor" href="#简历" aria-label="Permalink to &quot;**简历**&quot;">​</a></h2><h3 id="项目经历详情" tabindex="-1">项目经历详情 <a class="header-anchor" href="#项目经历详情" aria-label="Permalink to &quot;项目经历详情&quot;">​</a></h3><h4 id="通过互联网学习ai-产品经理" tabindex="-1">通过互联网学习AI+产品经理 <a class="header-anchor" href="#通过互联网学习ai-产品经理" aria-label="Permalink to &quot;通过互联网学习AI+产品经理&quot;">​</a></h4><p>Product Manager 自雇 入职日期2020年10月 – 2021年3月 任职时长4 个月</p><p>所在地点 中国 浙江省</p><ul><li>通过互联网学习AI+产品经理，简历见<a href="https://stevenjokess.github.io/2bPM/get_started.html" target="_blank" rel="noreferrer">https://stevenjokess.github.io/2bPM/get_started.html</a></li><li>背景：传统的招聘方由于求职方是否了解AI产品经理的职位要求以及公司情况而要求简历、设立面试环节（原有解决方案），而由于简历篇幅有限只能展示部分、时间有限往往只能出几个问题，不能确保全面考察到了面试者的能力，而这时求职方往往只有为数不多的时间去应答，极度考验临场反应来对答案进行表述，相比之前的积攒的能力这种情况有很强的随机性。</li><li>动机：为了公司（UCD）能尽快全面了解到我个人的能力(已经熟悉AI产品规划流程与设计工具(如Axure))，以最快捷最有效地招募到人才（哈哈哈，王婆卖瓜），而写出这本书（此时书即预备产品，我即产品经理）。</li><li>目标用户主要是招聘方，等待您需求的验证！同时可以给一些想一同成为AI金融产品经理的同学（不过你是我的竞品哎）提供参考，以最快捷最有效地招募到人才（哈哈哈，王婆卖瓜），而写出这本书（此时书即预备产品，我即产品经理）。</li><li>同时欢迎讨论与反馈：<a href="https://github.com/StevenJokess/2bPM/issues" target="_blank" rel="noreferrer">https://github.com/StevenJokess/2bPM/issues</a></li></ul><hr><h4 id="移动深度学习开发、测试" tabindex="-1">移动深度学习开发、测试 <a class="header-anchor" href="#移动深度学习开发、测试" aria-label="Permalink to &quot;移动深度学习开发、测试&quot;">​</a></h4><p>Developer(test) 自雇 入职日期2020年8月 – 2020年9月 任职时长1 个月</p><p>所在地点 中国 浙江省</p><p>项目描述:</p><ul><li><p>背景：手机是最常用的硬件设备，所以了解mobile AI的开发是非常必要的。</p></li><li><p>动机：了解Andriod开发。</p></li><li><p>目标用户：我自己了解Andriod开发。</p></li><li><p>项目：尝试测试了各个开源项目：</p></li><li><p>观看pytorch官方文档和视频,了解了基本的andriod开发体系;</p></li><li><p>动手完成了针对动物的图片识别项目:<a href="https://github.com/StevenJokess/pytorch-andriod-greatdemo" target="_blank" rel="noreferrer">https://github.com/StevenJokess/pytorch-andriod-greatdemo</a>;</p></li><li><p>并通过<a href="https://stevenjokess.github.io/post/pytorch-android/%E6%9D%A5%E5%88%86%E4%BA%AB%E7%BB%8F%E5%8E%86" target="_blank" rel="noreferrer">https://stevenjokess.github.io/post/pytorch-android/来分享经历</a></p></li><li><p>项目职责: 同时了解了arm体系和测试了其他框架:</p></li><li><p><a href="https://github.com/StevenJokess/Pytorch-Kotlin-Demo" target="_blank" rel="noreferrer">https://github.com/StevenJokess/Pytorch-Kotlin-Demo</a></p></li><li><p><a href="https://github.com/StevenJokess/djl-android-demo" target="_blank" rel="noreferrer">https://github.com/StevenJokess/djl-android-demo</a></p></li><li><p><a href="https://github.com/StevenJokess/paddlelite-andriod-demo" target="_blank" rel="noreferrer">https://github.com/StevenJokess/paddlelite-andriod-demo</a></p></li></ul><h4 id="动手学深度学习gan开发者" tabindex="-1">动手学深度学习GAN开发者 <a class="header-anchor" href="#动手学深度学习gan开发者" aria-label="Permalink to &quot;动手学深度学习GAN开发者&quot;">​</a></h4><p>开始时间: 2020-09-01</p><p>结束时间: 2020-11-01</p><p>项目描述:</p><ul><li>背景：PyTorch/TF2/MXNet为最常用的三大开源深度学习框架，而实际工作中，开发者往往会遇到版本问题（非最新），由于生产环境、研究目的等原因需要转化各个框架的训练等常见问题。</li><li>动机：解决常见的版本问题、框架训练转化问题，减少各个框架间的迁移时间成本，同时加速认识AI同行。</li><li>目标用户：PyTorch/TF2/MXNet开发者</li><li>实际项目：</li><li>GAN(MXNet-&gt;PyTorch&amp;TF2): <a href="http://preview.d2l.ai/d2l-en/PR-1716/chapter_generative-adversarial-networks/gan.html" target="_blank" rel="noreferrer">http://preview.d2l.ai/d2l-en/PR-1716/chapter_generative-adversarial-networks/gan.html</a></li><li>DCGAN(MXNet-&gt;PyTorch）:<a href="http://d2l.ai/chapter_generative-adversarial-networks/dcgan.html" target="_blank" rel="noreferrer">http://d2l.ai/chapter_generative-adversarial-networks/dcgan.html</a></li><li>结果：共300+浏览，领英加了400左右的AI深度学习同行。(已经被封，见<a href="https://stevenjokess.github.io/2bPM/AI_pipan.html#id27" target="_blank" rel="noreferrer">https://stevenjokess.github.io/2bPM/AI_pipan.html#id27</a>)</li></ul><hr><ul><li>背景：MXNet死气沉沉，只有问题没有回答。</li><li>动机：解决MXNet社区死气沉沉。</li><li>目标用户：MXNet开发者</li><li>开设d2l-en-read记录自己所有的学习过程.见<a href="https://github.com/StevenJokess/d2l-en-read/tree/moreme" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/tree/moreme</a></li><li>积极参与discuss.d2l.ai,记录自己遇到的坑,被李沐(MXNet开发者)评为最活跃的参与者.</li><li>和mxnet的开发者表达对社区的死气沉沉的不满,并提出活跃社区建议,后被采纳开设discussion区.（<a href="https://github.com/apache/incubator-mxnet/issues/18931%EF%BC%89" target="_blank" rel="noreferrer">https://github.com/apache/incubator-mxnet/issues/18931）</a></li></ul><hr><h4 id="完成学位论文" tabindex="-1">完成学位论文 <a class="header-anchor" href="#完成学位论文" aria-label="Permalink to &quot;完成学位论文&quot;">​</a></h4><p>开始时间: 2020-02-01</p><p>结束时间: 2020-05-01</p><p>项目描述: 独立研究者 repo: <a href="https://github.com/StevenJokess/gra_paper" target="_blank" rel="noreferrer">https://github.com/StevenJokess/gra_paper</a></p><ul><li>运用知网、Google学术、SciHub等学术搜索引擎,完成文献综述和翻译.</li><li>由于导师没接触过Python,我独立阅读Python文档、十余本相关书籍.</li><li>项目职责: 运用Pandas库的DataReader()、datetime()导入股市数据.</li><li>to_excel()导出,后Excel处理缺失数据与整合文件;read_excel()读取,plt、seaborn库生成时间序列图.</li><li>Statsmodel库的极大似然估计下fit()出VAR模型,as_csv()来保存结果.</li><li>Word完成编写、排版,共13656字的《中美贸易摩擦前后中美股市的联动性分析》</li></ul><h3 id="相关课程" tabindex="-1">相关课程: <a class="header-anchor" href="#相关课程" aria-label="Permalink to &quot;相关课程:&quot;">​</a></h3><ul><li>数学分析(95);高等代数(89);概率论与数理统计(85);大学英语(90)</li><li>计算机基础--PS(90);计算机高级语言--C语言(100);网络金融(80);</li><li>微观经济学(85);宏观经济学(90);计量经济学(82);投资学(82补考);金融计量学(85);</li><li>会计循环实验(91);计量经济学实验(90);证券投资模拟交易(89);EXCEL计算实验(86);商业银行综合业务</li><li>实验(87);投资组合管理(81);财务报表分析(80);</li><li>金融服务营销(93);金融从业综合素质实训(92);毕业实习(88);</li></ul><p><img src="'+h+'" alt="跳绳证书、六级"></p><p>证券、基金证书纸质版还没领：<img src="'+p+'" alt="证从1"><img src="'+d+'" alt="证从2"><img src="'+b+'" alt="基从">。</p><p>B站跳绳视频：<a href="https://www.bilibili.com/video/BV1Wf4y167Kp" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Wf4y167Kp</a></p><h2 id="百度开发者版想法" tabindex="-1">百度开发者版想法： <a class="header-anchor" href="#百度开发者版想法" aria-label="Permalink to &quot;百度开发者版想法：&quot;">​</a></h2><p><strong>一面百度AIstudio产品经理失败</strong>后的总结：<a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/aistudio-job.md" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/aistudio-job.md</a></p><p><img src="'+m+'" alt="baidu开发者版"></p><p><img src="'+c+'" alt="git时间"></p><p>可以看到2020年10月3日里面就有最近<strong>才beta测试</strong>的 <a href="https://kaifa.baidu.com" target="_blank" rel="noreferrer">https://kaifa.baidu.com</a> 的主意!</p><p>据我能找到的最早时间：</p><p><img src="'+g+'" alt="能找到的最早时间"></p><p>百度股价预测：</p><p><img src="'+u+'" alt="百度股价"> :depth:300px</p><p>百度最新股价：</p><p><img src="'+_+'" alt="百度最新股价"> :depth:200px</p><p><a href="https://www.overleaf.com/project/603dfbba8126ff225dc18564" target="_blank" rel="noreferrer">https://www.overleaf.com/project/603dfbba8126ff225dc18564</a></p>',55),e("p",null,[e("embed",{width:"100%",height:"100%",fullscreen:"yes",src:"/蔡舒起-AI产品经理-动手学深度学习GAN开发者_nophone.pdf"})],-1),e("h2",{id:"收款码",tabindex:"-1"},[t("收款码 "),e("a",{class:"header-anchor",href:"#收款码","aria-label":'Permalink to "收款码"'},"​")],-1),e("p",null,[t("首先第一步，反抗同人的真正活动和本质属性相背离相割裂的“资本”"),e("a",{href:"https://marxism.pku.edu.cn/xzlt/1296.htm",target:"_blank",rel:"noreferrer"},"^4"),t('，为了我继续符合我本质的活动，将放上收款码，如果对你有帮助或仅仅为了帮助我，请支持一二，在家失业两年，虽然包吃住，但是全职被骂，也不好受，而且再没资本主义下的“收入”，马上就要被赶出来了！"人们首先必须吃、喝、住、穿，然后才能从事政治、科学、艺术、宗教等等；[^794]"（：共产主义快点实现！')],-1),e("ul",null,[e("li",null,[t("当当代的恩格斯，送点你的闲钱：）赞助我 "),e("img",{src:a,alt:"收款码"})]),e("li",null,"也可以邮箱发送你可能的联系方式，交友：llgg8679@qq.com")],-1)])])}const q=i(f,[["render",k]]);export{B as __pageData,q as default};
